}

/**
 * Compares the snapshots of the two dates; a blank to-date compares with now. Re-read from the store
 * first, so every person's snapshots and due-total are as the store holds them; the old lines are gone meanwhile.
 */
protected async compareSnapshots(from: string, to: string): Promise<void> {
  this.snapshotDates.set(null);
  if (!(await this.reloadForExport())) return;
  this.snapshotDates.set({ from, to });
}

/** A comparison line, its figures in the user's locale; an empty figure leaves no trailing space. */
protected snapshotLine(l: { name: string; then: string; now: string }): string {
  const locale = this.session.locale();
  return [l.name, formatFigure(l.then, locale), formatFigure(l.now, locale)].join(' ').trim();
}

/** Their due-total, or n/a. */
protected dueTotalOf(p: Person): string {
  const total = this.dueTotalCents(p);
  return total === null ? NA : money(total);
}

/**
 * Downloads everyone, retired people included, in list order as CSV: name, grade in force today,
 * retired-from (or nothing) and due-total as shown. Re-read from the store first, so while an as-of
 * date is set it holds the as-of figures.
 */
protected async exportCsv(): Promise<void> {
  if (!(await this.reloadForExport())) return;
  const lines = [['name', 'grade', 'retired-from', 'due-total'], ...this.people().map((p) => [p.name, this.gradeOf(p), p.retiredFrom ?? '', this.dueTotalOf(p)])];
  downloadCsv(lines, 'people.csv');
}

